source("pre.R")
set.seed(11); two <- as.bigz(2)
for (ty in c("int64", "uint64", "int128", "uint128")) { f <- get(ty); w <- if (grepl("64", ty)) 64 else 128; sg <- !grepl("^u", ty)
  pool <- c(urand.bigz(300, w - 1), urand.bigz(50, 10), as.bigz(0:20)); if (sg) pool <- c(pool, -pool)
  ch <- c(as.character(pool), NA)
  for (r in 1:30) {
    xs <- sample(ch, sample(c(0, 1, 5, 2000), 1), TRUE); ts <- sample(ch, sample(c(0, 1, 7, 3000), 1), TRUE)
    x <- f(xs); t <- f(ts)
    e <- match(xs, ts)
    if (!identical(zu_match(x, t), e)) cat("MISMATCH zu_match", ty, "\n")
    if (!identical(match(x, t), e)) cat("MISMATCH match", ty, "\n")
    if (!identical(x %zin% t, xs %in% ts)) cat("MISMATCH zin", ty, "\n")
    if (!identical(x %in% t, xs %in% ts)) cat("MISMATCH in", ty, "\n")
    if (!identical(duplicated(x), duplicated(xs))) cat("MISMATCH dup", ty, "\n")
    if (!identical(duplicated(x, fromLast = TRUE), duplicated(xs, fromLast = TRUE))) cat("MISMATCH dupL", ty, "\n")
    if (!identical(as.character(unique(x)), unique(xs))) cat("MISMATCH unique", ty, "\n")
    if (!identical(anyDuplicated(x), anyDuplicated(xs))) cat("MISMATCH anydup", ty, "\n")
    if (!identical(anyDuplicated(x, fromLast = TRUE), anyDuplicated(xs, fromLast = TRUE))) cat("MISMATCH anydupL", ty, "\n")
    if (length(xs)) { tb <- table(x, useNA = "ifany"); te <- table(xs, useNA = "ifany"); if (!identical(as.vector(tb[order(names(tb))]), as.vector(te[order(names(te))])) || !identical(sort(names(tb)), sort(names(te)))) cat("MISMATCH table", ty, "\n")
      nn <- names(table(x)); bz <- as.bigz(nn); if (length(bz) > 1 && any(diff(as.numeric(xtfrm(f(nn)))) <= 0)) cat("MISMATCH table order", ty, "\n")
      o <- order(x); xo <- xs[o]; nna <- sum(!is.na(xs)); if (nna > 1) { v <- as.bigz(xo[seq_len(nna)]); if (any(v[-1] < v[-nna])) cat("MISMATCH order", ty, "\n") }; if (any(!is.na(xo[seq_len(nna)])) && anyNA(xo[seq_len(nna)])) cat("MISMATCH order NA", ty, "\n")
      rk <- xtfrm(x); k <- !is.na(xs); if (any(k)) { v <- as.bigz(xs[k]); ex <- vapply(seq_along(v), function(j) sum(v < v[j]) + 1L, 0L); if (length(v) <= 5 && !identical(as.integer(rk[k]), ex)) cat("MISMATCH xtfrm", ty, "\n") }
    }
  }
}
